   204  cmp_nonblank(const char *key, const unsigned char *u, const unsigned char *ulim)
   205  {
   206      const unsigned char *ukey = (const unsigned char *) key;
   207
   208      while (*ukey)
   209          if (u >= ulim) return +1;
   210          else if (isspace_c(*u)) u++;
   211          else if (*u != *ukey) return (*ukey < *u)? -1 : +1;
   212          else u++, ukey++;
