   242  // Parse tab-delimited text, filling in a string of column types and returning
   243  // the number of columns spotted (within [u,ulim), and up to column_len) or -1
   244  // if non-printable characters were seen.  Column types:
   245  //     i: integer, s: strand sign, C: CIGAR, O: SAM optional field, Z: anything
   246  static int
   247  parse_tabbed_text(char *columns, int column_len,
   248                    const unsigned char *u, const unsigned char *ulim,
   249                    int *complete)
   250  {
   251      const char *str  = (const char *) u;
   252      const char *slim = (const char *) ulim;
   253      const char *s;
   254      int ncolumns = 0;
   255
   256      enum { digit = 1, leading_sign = 2, cigar_operator = 4, other = 8 };
   257      unsigned seen = 0;
   258      *complete = 0;
   259
   260      for (s = str; s < slim; s++)
   261          if (*s >= ' ') {
   262              if (isdigit_c(*s))
   263                  seen |= digit;
   264              else if ((*s == '+' || *s == '-') && s == str)
   265                  seen |= leading_sign;
   266              else if (strchr(BAM_CIGAR_STR, *s) && s > str && isdigit_c(s[-1]))
   267                  seen |= cigar_operator;
   268              else
   269                  seen |= other;
   270          }
   271          else if (*s == '\t' || *s == '\r' || *s == '\n') {
   272              size_t len = s - str;
   273              char type;
   274
   275              if (seen == digit || seen == (leading_sign|digit)) type = 'i';
   276              else if (seen == (digit|cigar_operator)) type = 'C';
   277              else if (len == 1)
   278                  switch (str[0]) {
   279                  case '*': type = 'C'; break;
   280                  case '+': case '-': case '.': type = 's'; break;
   281                  default: type = 'Z'; break;
   282                  }
   283              else if (len >= 5 && str[2] == ':' && str[4] == ':') type = 'O';
   284              else type = 'Z';
   285
   286              columns[ncolumns++] = type;
   287              if (*s != '\t' || ncolumns >= column_len - 1) {
   288                  *complete = 1; // finished the line or more columns than needed
   289                  break;
   290              }
   291
   292              str = s + 1;
   293              seen = 0;
   294          }
   295          else return -1;
   296
   297      columns[ncolumns] = '\0';
   298      return ncolumns;
   299  }
   300
   470              fmt->category = index_file;
   471              fmt->format = fai_format;
   472              return 0;
   473          }
   474          else if (colmatch(columns, "Zii+") >= 3) {
